import os
import sys
import stat
import time
import platform
import datetime
import traceback
from typing import Callable
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.stream.aasyslog.exceptions import TimeoutException, FileProtocolClientError


def get_builtin_value(param_name, default=None):
    """
    Get robot builtin  variable value, default will return if variable not found
    :param param_name: variable name
    :param default: default value to return if variable not available
    """
    return BuiltIn().get_variable_value('${{{}}}'.format(param_name), default)


def wait_until_method_succeed(timeout: int, interval: float, method: Callable, raise_error=True, **kwargs):
    end_time = time.monotonic() + timeout
    while True:
        try:
            return method(**kwargs)
        except:
            exc_type, exc_value, exc_traceback = sys.exc_info()
        time.sleep(interval)
        if time.monotonic() > end_time:
            break
    if raise_error:
        traceback.print_exception(exc_type, exc_value, exc_traceback)
        raise TimeoutException(exc_value)


def run_method_with_ignore_error(func, *args, **kwargs):
    try:
        return func(*args, **kwargs)
    except:
        pass


def is_linux_platform():
    return True if "Linux" in platform.platform() else False


def current_datatime():
    now = datetime.datetime.now().strftime('%Y-%m-%d_%H:%M:%S')
    if not is_linux_platform():
        now = now.replace(":", "-")
    return now


def create_directory_if_not_exist(path):
    if not os.path.isdir(path):
        os.mkdir(path)
    return path


def verify_local_path_exists_and_is_dir(local_path):
    if not os.path.exists(local_path):
        _raise_no_such_dir(local_path)
    if not os.path.isdir(local_path):
        _raise_not_dir(local_path)


def verify_remote_paths_exist_and_not_dir(paths, fp, timeout):
    for path in paths:
        try:
            remote_stat = fp.stat(path, timeout)
            is_dir = stat.S_ISDIR(remote_stat.st_mode)
        except IOError:
            _raise_no_such_file(path)
        if is_dir:
            _raise_is_dir(path)


def get_full_destination_paths(source_file_paths, destination_dir_path):
    full_destination_paths = []
    for path in source_file_paths:
        full_destination_path = _get_destination_path(path, destination_dir_path)
        full_destination_paths.append(full_destination_path)

    return full_destination_paths


def _get_destination_path(source_path, destination_dir_path):
    filename = os.path.basename(source_path)
    full_path = os.path.join(destination_dir_path, filename)
    return full_path


def _raise_no_such_dir(path):
    exc_msg = "No such directory: {}".format(path)
    raise FileProtocolClientError(exc_msg)


def _raise_not_dir(path):
    exc_msg = "Not a directory: {}".format(path)
    raise FileProtocolClientError(exc_msg)


def _raise_no_such_file(path):
    exc_msg = "No such file: {}.".format(path)
    raise FileProtocolClientError(exc_msg)


def _raise_is_dir(path):
    exc_msg = "Is a directory: {}.".format(path)
    raise FileProtocolClientError(exc_msg)
